import zipfile


class ZipFileProcessor:
    READ_MODE = 'r'
    WRITE_MODE = 'w'

    def __init__(self, file_name):
        self.file_name = file_name

    def read_zip_file(self):
        try:
            zip_file = zipfile.ZipFile(self.file_name, self.READ_MODE)
            return zip_file
        except Exception:
            return None

    def extract_all(self, output_path):
        return self._perform_zip_operation(lambda zf: zf.extractall(output_path))

    def extract_file(self, file_name, output_path):
        return self._perform_zip_operation(lambda zf: zf.extract(file_name, output_path))

    def create_zip_file(self, files, output_file_name):
        try:
            with zipfile.ZipFile(output_file_name, self.WRITE_MODE) as zip_file:
                self._write_files(zip_file, files)
            return True
        except Exception:
            return False

    def _write_files(self, zip_file, files):
        for file in files:
            zip_file.write(file)

    def _perform_zip_operation(self, operation):
        try:
            with zipfile.ZipFile(self.file_name, self.READ_MODE) as zip_file:
                operation(zip_file)
            return True
        except Exception:
            return False

    @property
    def file_name(self):
        return self._file_name

    @file_name.setter
    def file_name(self, value):
        self._file_name = value

    def __init__(self, file_name):
        self._file_name = file_name
